  ('Pumpkin Creek', 'Creek', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-103.50696160841989, 41.62519018384401), 4326)::extensions.geography),
  ('Deep Holes Creek', 'Creek', 'freshwater'::public.water_type_enum, ST_SetSRID(ST_MakePoint(-102.93688693322812, 41.58617222083076), 4326)::extensions.geography),
